from produire import produire,paras,table,steps
from medicaments import pilocarpine
parts=[
('La maladie de Sjögren est une maladie auto-immune pouvant associer sécheresse et atteintes systémiques. Les {distinctions diagnostiques} évitent d’assimiler tout syndrome sec à cette maladie.',paras('Le terme syndrome de Sjögren reste présent dans certaines notices. Une sécheresse isolée peut avoir d’autres causes ; le diagnostic confronte clinique, fonction glandulaire, immunologie et parfois histologie.')),
('La présentation et l’âge de début sont variables. Les {contextes de suspicion} vont au-delà d’une bouche sèche chez une femme adulte.',paras('La maladie peut aussi toucher l’homme et l’enfant ; une tuméfaction salivaire peut être au premier plan. Elle peut coexister avec une autre maladie auto-immune et ne doit pas être écartée uniquement sur un profil démographique inhabituel.')),
('L’atteinte immune des glandes exocrines perturbe salive et larmes. Les {conséquences systémiques} justifient une évaluation qui dépasse le confort buccal.',paras('Fatigue, arthralgies et atteintes cutanées, neurologiques, pulmonaires ou rénales peuvent s’associer. L’activation lymphocytaire est également liée à un risque accru de lymphome chez une partie des patients.')),
('Une tuméfaction glandulaire nouvelle doit être explorée précocement. Les {signes d’alarme} recherchent lymphome et atteinte d’organe.',paras('Glande augmentant durablement de volume, adénopathies, purpura, fièvre inexpliquée, sueurs nocturnes ou amaigrissement imposent un bilan. Douleur oculaire avec baisse visuelle, dyspnée, déficit neurologique ou atteinte rénale suspectée nécessitent une évaluation adaptée à leur gravité.')),
('L’entretien précise sécheresse oculaire et buccale, durée et retentissement. Les {questions systémiques} incluent fatigue, douleurs et épisodes glandulaires.',paras('Demander besoin de boire pour avaler les aliments secs, caries nouvelles, sensation de sable oculaire et gonflements des glandes. Revoir médicaments, radiothérapie et autres causes de sécheresse ; rechercher symptômes pulmonaires, neurologiques, cutanés et rénaux.')),
('Examiner muqueuses, dents, glandes et ganglions. Les {éléments extrabuccaux} orientent la suite du bilan.',paras('Décrire salive, candidose éventuelle, état dentaire et asymétrie glandulaire. Rechercher purpura et manifestations articulaires ; une évaluation ophtalmologique objective la sécheresse et les lésions de surface.')),
('Le syndrome sec possède de nombreuses causes. Le {diagnostic différentiel} doit être traité avec autant d’attention que les autoanticorps.',table(['Profil','Alternative ou association'],[['Polymédication anticholinergique.','Xérostomie médicamenteuse.'],['Antécédent d’irradiation cervico-faciale.','Atteinte post-radiothérapie.'],['Soif et polyurie.','Cause métabolique.'],['Gonflement salivaire douloureux aux repas.','Obstacle canalaire.'],['Tuméfaction persistante ou signes atypiques.','Autre maladie glandulaire, inflammatoire ou lymphoproliférative.']])) ,
('Aucun symptôme ni test isolé ne résume le diagnostic. Les {arguments objectifs} sont interprétés par une équipe compétente.',paras('Évaluation de sécrétion salivaire, tests oculaires, anticorps anti-Ro/SSA et histologie labiale selon indication sont combinés. Les critères de classification aident à standardiser les situations mais ne remplacent pas le diagnostic clinique ; une sérologie négative n’exclut pas toutes les formes.')),
('Le bilan précise maladie, retentissement et complications. Les {examens complémentaires} sont choisis selon la suspicion.',paras('Des anticorps ciblés peuvent être indiqués même si un dépistage initial d’anticorps antinucléaires est négatif lorsque la suspicion reste forte. Une biopsie des glandes salivaires labiales se discute si clinique et sérologie ne permettent pas de conclure.', 'L’échographie glandulaire par un opérateur expérimenté apporte des arguments, sans remplacer automatiquement sérologie ou histologie. Un test salivaire isolé normal ne suffit pas à exclure toute maladie ; le contexte et les autres résultats comptent. Le bilan systémique est orienté par les manifestations.')),
('L’{arbre de prise en charge} relie confirmation, protection des surfaces et recherche d’atteinte d’organe. La sécheresse et les manifestations systémiques n’ont pas le même traitement.',steps('Rechercher causes alternatives et signes urgents, puis adresser pour confirmation si la suspicion persiste.', 'Objectiver atteinte salivaire et oculaire, compléter immunologie et éventuellement histologie.', 'Protéger bouche et yeux, traiter les complications et évaluer la fonction glandulaire résiduelle.', 'Traiter les atteintes systémiques avec le spécialiste et surveiller les signes d’évolution, notamment glandulaires et ganglionnaires.')),
('Le traitement symptomatique repose sur soins dentaires, substituts et stimulation adaptée. Les {modalités de la pilocarpine} demandent une vérification des contre-indications.',paras('Les immunosuppresseurs ne sont pas prescrits systématiquement pour une simple sécheresse : ils répondent à des indications systémiques spécialisées. Une fonction glandulaire résiduelle peut permettre un bénéfice d’un traitement stimulant.', '@@MEDICAMENTS@@')),
('Le {suivi régulier} protège dents, muqueuses et yeux. Il doit aussi détecter une manifestation systémique nouvelle.',paras('Hygiène fluorée et prévention dentaire personnalisée selon le risque carieux ; traiter candidose et problèmes prothétiques. Organiser un suivi ophtalmologique et rhumatologique, et expliquer de signaler une tuméfaction persistante, des ganglions ou des symptômes généraux nouveaux.')),
('Une sécheresse n’est pas synonyme de Sjögren. Le diagnostic combine plusieurs arguments objectifs. Une nouvelle tuméfaction glandulaire impose un bilan précoce. Le traitement de la sécheresse ne remplace pas celui d’une atteinte systémique.','')]
quiz=[('Une bouche sèche suffit-elle au diagnostic ?','Non.'),('Un homme ou un enfant peut-il être atteint ?','Oui.'),('Quels autres organes exocrines sont souvent concernés ?','Les glandes lacrymales, avec sécheresse oculaire.'),('La maladie peut-elle être systémique ?','Oui : atteintes articulaires, cutanées, pulmonaires, rénales ou neurologiques selon les cas.'),('Une sérologie négative exclut-elle toute maladie ?','Non.'),('Quand discuter une biopsie labiale ?','Si la suspicion persiste et que clinique et sérologie ne permettent pas de conclure.'),('L’échographie remplace-t-elle automatiquement histologie et anticorps ?','Non.'),('Un test salivaire normal isolé suffit-il à exclure ?','Non : confronter tous les arguments.'),('Que faire devant un nouveau gonflement glandulaire persistant ?','Explorer précocement, notamment pour un lymphome.'),('Une immunosuppression est-elle systématique pour une bouche sèche ?','Non : elle répond à des indications systémiques précises.'),('Quelle dose adulte de Salagen figure dans la notice pour Sjögren ?','5 mg quatre fois par jour, sous réserve des contre-indications et adaptations.'),('Est-ce la même dose initiale qu’après radiothérapie ?','Non : la notice indique 5 mg trois fois par jour après radiothérapie.'),('Pourquoi surveiller hydratation sous pilocarpine ?','La sudation peut être importante et favoriser une déshydratation.'),('Un asthme non maîtrisé permet-il ce traitement ?','Non : c’est une contre-indication de la notice.')]
produire(7,parts,quiz,(8,15,18),pilocarpine)
